#!/usr/bin/env bash
set -euo pipefail
python3 - <<'PYTHON'
from pathlib import Path
import base64,gzip,json,re,datetime,os,shutil
service=Path('/etc/systemd/system/warlords2-coop.service').read_text()
roots=set(re.findall(r'/opt/warlords2/releases/[^/\s";]+',service))
assert len(roots)==1,'Cannot identify active release; no files changed'
root=Path(next(iter(roots)))/'种族战役2复刻'
files=json.loads(gzip.decompress(base64.b64decode('')))
for name in files:
 assert (root/name).is_file(), 'Missing '+name
assert '0.10.3-native-weapons' in (root/'coop-local-server.cjs').read_text(), 'Unexpected server version'
backup=Path('/opt/warlords2/backups')/('loading-fix-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S'))
backup.mkdir(parents=True)
for name in files: shutil.copy2(root/name,backup/name)
try:
 for name,content in files.items():
  temp=root/(name+'.loadfix.tmp');temp.write_text(content,encoding='utf-8');temp.chmod(0o644);os.replace(temp,root/name)
except Exception:
 for name in files: shutil.copy2(backup/name,root/name)
 raise
rollback='#!/usr/bin/env bash\nset -euo pipefail\n'+''.join('cp -a "'+str(backup/name)+'" "'+str(root/name)+'"\n' for name in files)
(backup/'rollback.sh').write_text(rollback,encoding='utf-8')
print('LOAD_FIX_OK')
print('Active directory:',root)
print('Backup:',backup)
print('Both players: Ctrl+F5 and create a new room.')
PYTHON
